pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value > 0 && _value <= type(uint256).max);
        c.NETM();

        uint256 supplyBefore = c.totalSupply();

        // bound _value to be <= balance of owner (which is totalDistributed after NETM)
        uint256 ownerBalance = c.balanceOf(address(this));
        vm.assume(_value <= ownerBalance);

        c.burn(_value);

        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter == supplyBefore - _value, "totalSupply should decrease by burn amount");
    }
}

