// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 burnValue) public {
        // Restrict burn value to be at most owner's balance (totalDistributed initially)
        vm.assume(burnValue <= 250000000e18);

        // Perform a burn with the given value
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnValue));

        // Now call NETM() to reset state (onlyOwner)
        vm.prank(c.owner());
        c.NETM();

        // General rule: after NETM(), totalSupply must be 500000000e18
        // The bug causes burn to revert when burnValue == owner's balance,
        // which leaves totalSupply unchanged at 500000000e18 if the burn reverted.
        // But the correct behavior burns exactly the balance, reducing totalSupply.
        // After NETM() resets, totalSupply should always be 500000000e18.
        assertTrue(c.totalSupply() == 500000000e18);
    }
}

