pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(amount <= 500000000e18);
        vm.prank(owner);
        // Call NETM() to set owner and balances
        c.NETM();
        uint256 balanceBefore = c.balanceOf(owner);
        if (balanceBefore == 0) return;
        uint256 totalSupplyBefore = c.totalSupply();
        // Try to burn exactly the owner's balance
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", balanceBefore));
        if (success) {
            // If burn succeeded, totalSupply must have decreased by balanceBefore
            assertTrue(c.totalSupply() == totalSupplyBefore - balanceBefore);
        } else {
            // If burn reverted (buggy version), totalSupply unchanged
            assertTrue(c.totalSupply() == totalSupplyBefore);
        }
    }
}

