pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 preBurnAmount) public {
        // Bound preBurnAmount to be less than totalDistributed to allow valid calls before NETM
        vm.assume(preBurnAmount < 250000000e18);

        // Optionally call transferFrom or other operations to change state
        // But we focus on the burn after NETM: we need only the owner's balance after NETM.

        // Call NETM to set owner's balance to totalDistributed
        c.NETM();

        // Get owner's balance after NETM
        address owner = address(this); // Since setUp and test run as this contract
        uint256 ownerBal = c.balanceOf(owner);

        // The rule: ownerBal equals totalDistributed (250000000e18)
        // And we can burn exactly that amount without revert
        // Attempt to burn ownerBal
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", ownerBal));

        // In reference C, burn(ownerBal) should succeed because _value <= balances[msg.sender]
        // In buggy M, burn(ownerBal) reverts because _value < balances[msg.sender] is false when equal
        assertTrue(success == true, "Burn of full owner balance should succeed in reference");
    }
}

