pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller) public {
        // Ensure caller is not the owner (owner is msg.sender in constructor)
        vm.assume(_caller != address(this));
        vm.assume(_caller != address(0));

        // Record totalDistributed before calling NETM()
        uint256 initialDistributed = c.totalDistributed();

        // Call NETM() from the caller
        vm.prank(_caller);
        c.NETM();

        // After NETM(), totalDistributed should be unchanged because the call distributes to owner
        // but the bug removes the increment. For the correct version, if _caller is owner,
        // totalDistributed is set to totalDistributed (same as owner balance).
        // The general rule: totalDistributed after NETM() equals totalDistributed before NETM()
        uint256 finalDistributed = c.totalDistributed();

        assertTrue(finalDistributed == initialDistributed, "totalDistributed should remain unchanged after NETM()");
    }
}

