import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user) public {
        vm.assume(user != address(0));
        uint256 initTotalDistributed = 250000000e18;
        uint256 initTotalSupply = 500000000e18;

        // Call NETM() which distributes totalDistributed to owner
        c.NETM();

        // After NETM(), the sum of balances (owner gets totalDistributed) should be at least initTotalDistributed
        // and not exceed totalSupply. This holds in reference because totalDistributed is added to balances and totalDistributed.
        // In buggy version, totalDistributed is not updated, but balances increase, so sum of balances exceeds totalSupply.
        uint256 totalBalances = c.balanceOf(address(this)) + c.balanceOf(user);
        bool rule = totalBalances >= initTotalDistributed && totalBalances <= initTotalSupply;
        assertTrue(rule);
    }
}

