pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _amount) public {
        // Bound amount to a reasonable range to avoid overflow
        vm.assume(_amount > 0 && _amount <= c.totalRemaining());

        // Record initial totalDistributed
        uint256 initialDistributed = c.totalDistributed();

        // Perform required setup: whitelist the owner and call NETM()
        vm.prank(address(0)); // Not owner, just to satisfy modifier
        // Actually need to call NETM() as owner
        // The original test had an issue - we need to call NETM() but it's onlyOwner
        // Let's restructure: we call getTokens() which is the public entry that calls distr
        vm.deal(address(this), _amount);
        vm.prank(address(this));
        c.getTokens();

        // Check that totalDistributed changed (reference) or didn't (mutant)
        uint256 finalDistributed = c.totalDistributed();

        // In the reference, totalDistributed should have increased by value
        // In the mutant (missing totalRemaining decrement), totalDistributed still increases
        // Actually the bug is removing totalRemaining -= _amount, not affecting totalDistributed
        // The difference is that after many calls, eventually totalRemaining would underflow

        // For the given difference: after NETM(), totalDistributed differs
        // NETM() sets balances[owner] = totalDistributed, but doesn't change totalDistributed
        // The difference is NOT in NETM() but in distr() called from getTokens()

        // Let's re-express: the invariant is that totalDistributed + totalRemaining should be constant
        // Actually let's check the invariant: totalDistributed + totalRemaining == totalSupply
        assertTrue(c.totalDistributed() + c.totalRemaining() == c.totalSupply());
    }
}

