pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callValue, uint256 times) public {
        // Bound the initial ether to send and the number of getTokens calls
        vm.assume(callValue >= 0.001 ether && callValue <= 10 ether);
        vm.assume(times > 0 && times <= 5);
        // Record totalDistributed before any calls
        uint256 totalBefore = c.totalDistributed();
        uint256 totalGiven = 0;
        // Make multiple getTokens calls (via receive) with decreasing values
        for (uint256 i = 0; i < times; i++) {
            // Each call sends a portion of the value
            uint256 amount = callValue / (i + 1);
            if (amount == 0) break;
            // Record totalRemaining before call
            uint256 remBefore = c.totalRemaining();
            // Send ether to trigger getTokens
            (bool success, ) = address(c).call{value: amount}("");
            if (!success) break;
            uint256 distributedNow = c.totalDistributed() - totalBefore - totalGiven;
            totalGiven += distributedNow;
        }
        // Now call NETM() - only owner can call, and owner is the contract deployer
        // but the test contract is not owner. The NETM() function will try to set owner and balances,
        // but since the deployer is the test contract, we can impersonate or directly call?
        // Actually, the constructor sets owner = msg.sender (the test contract).
        // So we can call NETM() directly.
        c.NETM();
        // The rule: after NETM(), totalDistributed should equal totalBefore + totalGiven
        // This is what the reference does: it sets totalDistributed to totalDistributed before NETM (which is totalBefore + totalGiven)
        // The mutant would set it to 0, so the rule fails.
        assertTrue(c.totalDistributed() == totalBefore + totalGiven);
    }
}

