// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value) public {
        // Bound the burn value to be <= balance of owner (which is totalDistributed after NETM)
        c.NETM();
        uint256 balance = c.balanceOf(address(this)); // owner's balance after NETM
        vm.assume(_value > 0 && _value <= balance);

        // Record totalDistributed before burn
        uint256 before = c.totalDistributed();

        c.burn(_value);

        uint256 after = c.totalDistributed();

        // In reference: after = before - _value
        // In bug: after = before + _value
        // So the invariant is: after should be < before (or at least not > before)
        assertTrue(after < before, "totalDistributed should decrease on burn");
    }
}

