pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // After NETM() is called, owner should be the deployer (this contract), not address(0)
        c.NETM();
        // Use the auto-generated getter for the public state variable 'owner'
        // Since 'owner' is not public, we read it via the only public getter that exposes it.
        // The contract has a function to transfer ownership; we use that to infer the owner.
        // Actually, we can check that after NETM(), calling transferOwnership with a non-zero address
        // should not result in owner being zero. But we need a general rule that holds on reference and fails on mutant.
        // The reference: after NETM(), owner = msg.sender (the deployer). Then transferOwnership(x) sets owner = x if x != 0.
        // The mutant: after transferOwnership(x) with x != 0, owner becomes address(0) instead of x.
        // So the rule: after calling NETM() and then transferOwnership(x) with a non-zero x, owner should not be zero.
        address x = address(1);
        c.transferOwnership(x);
        // Since owner is not public, we can't read it directly. But we can use the fact that onlyOwner modifier allows or denies calls.
        // A simpler approach: after transferOwnership(x), the owner should be x (non-zero). If mutant sets it to zero, then subsequent
        // calls requiring onlyOwner will revert because msg.sender (this contract) is no longer owner.
        // So we can test: after the sequence, a call to withdraw() (onlyOwner) should succeed (not revert).
        // On reference, owner = x, so msg.sender (this contract) is owner, withdraw succeeds.
        // On mutant, owner = address(0), so withdraw reverts.
        // This is a general rule: after NETM() and transferOwnership(x) with x != 0, withdraw() should not revert.
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(success, "withdraw should succeed");
    }
}

